public partial class DeutschPatcher {
 const int Sector=2048;
 const string RulesHash="7c72b55366546080544d603fbe4f24aa128d80c043a56cad36db4db40327266b";
 static string Package=AppDomain.CurrentDomain.BaseDirectory;
 static XmlDocument Rules=new XmlDocument();
 static Dictionary<string,string> Assets=new Dictionary<string,string>();
 static string Hash(string path){using(var f=File.OpenRead(path))return Hash(f,f.Length);}
 static string Hash(Stream s,long n){using(var h=SHA256.Create()){byte[] b=new byte[2*1024*1024];while(n>0){int c=s.Read(b,0,(int)Math.Min(b.Length,n));if(c==0)throw new Exception("Datei unvollstaendig");h.TransformBlock(b,0,c,b,0);n-=c;}h.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(h.Hash).Replace("-","").ToLowerInvariant();}}
 static void Require(bool yes,string message){if(!yes)throw new Exception(message);}
 static string A(XmlNode e,string a){return e.Attributes[a].Value;}
 static byte[] Hex(string s){byte[] b=new byte[s.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(s.Substring(i*2,2),16);return b;}
 static byte[] Read(Stream f,long at,int n){f.Position=at;byte[] b=new byte[n];int done=0;while(done<n){int c=f.Read(b,done,n-done);if(c==0)throw new Exception("Unerwartetes Dateiende");done+=c;}return b;}
 static uint Both(byte[] b,int i){uint le=BitConverter.ToUInt32(b,i);uint be=(uint)(b[i+4]*16777216L+b[i+5]*65536+b[i+6]*256+b[i+7]);Require(le==be,"ISO-Byteordnungen widersprechen sich");return le;}
 static void PutBoth(Stream f,long at,uint value){byte[] b=BitConverter.GetBytes(value);f.Position=at;f.Write(b,0,4);Array.Reverse(b);f.Write(b,0,4);}
 static void CopySpan(Stream src,Stream dst,long at,long n){src.Position=at;byte[] b=new byte[2*1024*1024];while(n>0){int c=src.Read(b,0,(int)Math.Min(n,b.Length));if(c==0)throw new Exception("Unvollstaendige Quelldatei");dst.Write(b,0,c);n-=c;}}
 class Entry{public long Record,Offset,Size;public bool Directory;}
 static Dictionary<string,Entry> Scan(string image){using(var f=File.OpenRead(image)){byte[] p=Read(f,16*Sector,Sector);Require(p[0]==1 && Encoding.ASCII.GetString(p,1,5)=="CD001" && p[6]==1,"Kein ISO9660-Abbild");Require(Both(p,80)*(long)Sector==f.Length,"ISO-Laenge stimmt nicht");var result=new Dictionary<string,Entry>(StringComparer.OrdinalIgnoreCase);var visited=new HashSet<long>();ScanDir(f,Both(p,158)*(long)Sector,Both(p,166),"",result,visited,0);return result;}}
 static void ScanDir(Stream f,long at,long length,string path,Dictionary<string,Entry> all,HashSet<long> seen,int depth){Require(depth<16 && at>=0 && at+length<=f.Length && seen.Add(at),"Ungueltiges ISO-Verzeichnis");long pos=0;while(pos<length){byte n=Read(f,at+pos,1)[0];if(n==0){pos=(pos/Sector+1)*Sector;continue;}Require(n>=34 && pos+n<=length && pos%Sector+n<=Sector,"Ungueltiger ISO-Eintrag");byte[] r=Read(f,at+pos,n);long record=at+pos;pos+=n;Require(33+r[32]<=r.Length && (r[25]&128)==0,"ISO-Eintrag nicht unterstuetzt");if(r[32]==1 && r[33]<2)continue;string name=Encoding.ASCII.GetString(r,33,r[32]).Split(new char[]{';'},StringSplitOptions.None)[0].TrimEnd('.').ToUpperInvariant();Require(name!="" && name!="." && name!=".." && !name.Contains("/") && !name.Contains("\\"),"Unsicherer ISO-Pfad");string key=path+name;var e=new Entry{Record=record,Offset=Both(r,2)*(long)Sector,Size=Both(r,10),Directory=(r[25]&2)!=0};Require(e.Offset+e.Size<=f.Length && !all.ContainsKey(key),"ISO-Grenzen oder Doppelpfad");all.Add(key,e);if(e.Directory)ScanDir(f,e.Offset,e.Size,key+"/",all,seen,depth+1);}}
 static string SpanHash(string image,Entry e){using(var f=File.OpenRead(image)){f.Position=e.Offset;return Hash(f,e.Size);}}
 static Dictionary<string,Entry> CheckImage(string source,XmlNode rule){Require(Hash(source)==A(rule,"sha"),"Unbekannte oder veraenderte Original-CD: "+Path.GetFileName(source));var entries=Scan(source);Require(entries.Values.Count(e=>!e.Directory)==int.Parse(A(rule,"count")),"Falsches Originalinventar");foreach(XmlNode e in rule.SelectNodes("Replace"))Require(entries.ContainsKey(A(e,"path")),"Originalressource fehlt: "+A(e,"path"));CheckNative(source,entries,rule,null);return entries;}
 static Dictionary<string,string> BitmapAssets(XmlNode rule){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(XmlNode n in rule.SelectNodes("Bitmap"))d.Add(A(n,"path"),Assets[A(n,"asset")]);return d;}
 static void CheckNative(string image,Dictionary<string,Entry> entries,XmlNode rule,string output){var changes=BitmapAssets(rule);var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Entry idx=entries["INDEX.001"],dat=entries["HARVEST.DAT"];Require(idx.Size%148==0,"XFILE-Indexlaenge falsch");using(var f=File.OpenRead(image)){byte[] index=Read(f,idx.Offset,(int)idx.Size);long cursor=0;using(var dst=output==null?null:new FileStream(output,FileMode.CreateNew,FileAccess.ReadWrite)){if(dst!=null)CopySpan(f,dst,dat.Offset,dat.Size);for(int i=0;i<index.Length;i+=148){byte[] rec=new byte[148];Buffer.BlockCopy(index,i,rec,0,148);Require(Encoding.ASCII.GetString(rec,0,4)=="XFLE","Falscher XFILE-Marker");long off=BitConverter.ToUInt32(rec,132),size=BitConverter.ToUInt32(rec,136);Require(off==cursor+148 && off+size<=dat.Size,"XFILE-Grenzen falsch");Require(Read(f,dat.Offset+cursor,148).SequenceEqual(rec),"XFILE-Index/Daten stimmen nicht ueberein");string name=Encoding.GetEncoding(1252).GetString(rec,4,128).Split(new char[]{'\0'},StringSplitOptions.None)[0].Replace('\\','/');if(changes.ContainsKey(name)){Require(found.Add(name) && BitConverter.ToUInt32(rec,140)==0 && size==new FileInfo(changes[name]).Length && BitConverter.ToUInt32(rec,144)==size,"XFILE-Grafik nicht ersetzbar: "+name);if(dst!=null){byte[] data=File.ReadAllBytes(changes[name]);dst.Position=off;dst.Write(data,0,data.Length);}}cursor=off+size;}Require(cursor==dat.Size && found.Count==changes.Count,"XFILE-Inventar unvollstaendig");}}}
 static void PatchImage(string path,XmlNode rule,string work){var old=Scan(path);string native=Path.Combine(work,"native.dat");CheckNative(path,old,rule,native);var replacements=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(XmlNode n in rule.SelectNodes("Replace"))replacements.Add(A(n,"path"),Assets[A(n,"asset")]);replacements.Add("HARVEST.DAT",native);string output=Path.Combine(work,"new.iso");using(var src=File.OpenRead(path))using(var dst=new FileStream(output,FileMode.CreateNew,FileAccess.Write)){CopySpan(src,dst,0,src.Length);dst.Flush(true);}Require(Hash(path)==Hash(output),"ISO-Arbeitskopie abweichend");using(var f=new FileStream(output,FileMode.Open,FileAccess.ReadWrite)){foreach(var kv in replacements){f.Position=f.Length;while(f.Position%Sector!=0)f.WriteByte(0);long off=f.Position;using(var src=File.OpenRead(kv.Value))CopySpan(src,f,0,src.Length);long size=f.Position-off;while(f.Position%Sector!=0)f.WriteByte(0);PutBoth(f,old[kv.Key].Record+2,checked((uint)(off/Sector)));PutBoth(f,old[kv.Key].Record+10,checked((uint)size));}PutBoth(f,16*Sector+80,checked((uint)(f.Length/Sector)));f.Flush(true);}var after=Scan(output);Require(old.Keys.OrderBy(x=>x).SequenceEqual(after.Keys.OrderBy(x=>x)),"ISO-Dateiliste veraendert");foreach(var kv in old){if(kv.Value.Directory)continue;string expected=replacements.ContainsKey(kv.Key)?Hash(replacements[kv.Key]):SpanHash(path,kv.Value);string actual=SpanHash(output,after[kv.Key]);Require(actual==expected,"CD-Pruefung fehlgeschlagen: "+kv.Key+" erwartet="+expected+" erhalten="+actual);}VerifyNativeOutput(path,output,old,after,rule);File.SetAttributes(path,FileAttributes.Normal);File.Delete(path);File.Move(output,path);File.Delete(native);}
 static void VerifyNativeOutput(string oldPath,string newPath,Dictionary<string,Entry> before,Dictionary<string,Entry> after,XmlNode rule){var changes=BitmapAssets(rule);Entry idx=before["INDEX.001"],dat=before["HARVEST.DAT"],newdat=after["HARVEST.DAT"];using(var a=File.OpenRead(oldPath))using(var b=File.OpenRead(newPath)){byte[] index=Read(a,idx.Offset,(int)idx.Size);Require(SpanHash(oldPath,idx)==SpanHash(newPath,after["INDEX.001"]),"Nativer Index veraendert");for(int i=0;i<index.Length;i+=148){byte[] r=index.Skip(i).Take(148).ToArray();long off=BitConverter.ToUInt32(r,132),size=BitConverter.ToUInt32(r,136);Require(Read(b,newdat.Offset+off-148,148).SequenceEqual(r),"Nativer Kopf veraendert");string name=Encoding.GetEncoding(1252).GetString(r,4,128).Split(new char[]{'\0'},StringSplitOptions.None)[0].Replace('\\','/');a.Position=dat.Offset+off;b.Position=newdat.Offset+off;string expected=changes.ContainsKey(name)?Hash(changes[name]):Hash(a,size);Require(Hash(b,size)==expected,"Native Ressource abweichend: "+name);}}}
 static void PatchExe(string p){XmlNode ex=Rules.SelectSingleNode("/HarvesterPatch/Executable");Require(Hash(p)==A(ex,"source"),"Original-EXE unbekannt");byte[] b=File.ReadAllBytes(p);int end=0;foreach(XmlNode e in ex.SelectNodes("Edit")){int at=int.Parse(A(e,"offset"));byte[] old=Hex(A(e,"old")),n=Hex(A(e,"new"));Require(at>=end && old.Length==n.Length && at+old.Length<=b.Length,"EXE-Delta ungueltig");for(int i=0;i<old.Length;i++){Require(b[at+i]==old[i],"EXE-Quellbytes abweichend");b[at+i]=n[i];}end=at+old.Length;}using(var ms=new MemoryStream(b))Require(Hash(ms,ms.Length)==A(ex,"target"),"Deutsche EXE-Pruefsumme falsch");File.SetAttributes(p,FileAttributes.Normal);File.WriteAllBytes(p,b);}
 static void GogLog(string p,string target){string raw=File.ReadAllText(p,Encoding.UTF8);string[] lines=raw.Replace("\r\n","\n").Split(new char[]{'\n'},StringSplitOptions.None);string old=lines.First(l=>l.StartsWith("Dir_0=")).Substring(6);var suffix=new Dictionary<string,string>{{"Dir_0",""},{"Dir_1","\\DOSBox"},{"Dir_2","\\cloud_saves"},{"File_0","\\DOSBox\\dosbox-0.74-2.1-harvester.tar.gz"},{"File_1","\\DOSBox\\dosbox.exe"},{"File_2","\\dosbox_harvester.conf"},{"File_3","\\dosbox_harvester_single.conf"},{"ValueData_0","\\DOSBox"}};var seen=new HashSet<string>();for(int i=0;i<lines.Length;i++){int at=lines[i].IndexOf('=');if(at<0)continue;string key=lines[i].Substring(0,at);if(suffix.ContainsKey(key)){Require(seen.Add(key) && string.Equals(lines[i].Substring(at+1),old+suffix[key],StringComparison.OrdinalIgnoreCase),"GOG-Pfadmetadaten unbekannt");lines[i]=key+"="+target+suffix[key];}}Require(seen.Count==8,"GOG-Pfadmetadaten unvollstaendig");File.SetAttributes(p,FileAttributes.Normal);File.WriteAllText(p,string.Join("\r\n",lines),new UTF8Encoding(true));}
 static void Inventory(string root,string dir,List<string> dirs,List<string> files){Require((File.GetAttributes(dir)&FileAttributes.ReparsePoint)==0,"Links/Junctions sind nicht erlaubt: "+dir);foreach(string d in Directory.GetDirectories(dir)){dirs.Add(d.Substring(root.Length+1));Inventory(root,d,dirs,files);}foreach(string f in Directory.GetFiles(dir)){Require((File.GetAttributes(f)&FileAttributes.ReparsePoint)==0,"Verknuepfte Quelldatei: "+f);files.Add(f.Substring(root.Length+1));}}
 static string Full(string p){return Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);}
 static void Install(string source,string target){source=Full(source);target=Full(target);Require(Directory.Exists(source),"Originalordner fehlt");Require(!Directory.Exists(target)&&!File.Exists(target),"Ziel existiert bereits; es wird nichts ueberschrieben: "+target);Require(!string.Equals(source,target,StringComparison.OrdinalIgnoreCase)&&!target.StartsWith(source+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!source.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Quelle und Ziel muessen getrennte Ordner sein");string pack=Full(Package);Require(!pack.StartsWith(source+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!source.StartsWith(pack+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!string.Equals(pack,source,StringComparison.OrdinalIgnoreCase),"Paket bitte ausserhalb des Originalordners entpacken");Require((File.GetAttributes(Path.GetDirectoryName(target))&FileAttributes.ReparsePoint)==0,"Ziel-Elternordner ist eine Verknuepfung");var videoManifest=ReadVideoManifest();var dirs=new List<string>();var files=new List<string>();Inventory(source,source,dirs,files);foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Critical"))Require(Hash(Path.Combine(source,A(e,"path")))==A(e,"sha"),"Englische EXE oder relative GOG-Konfiguration unbekannt: "+A(e,"path"));foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Image")){Console.WriteLine("Pruefe "+A(e,"name"));CheckImage(Path.Combine(source,A(e,"name")),e);}foreach(string f in new[]{"goglog.ini","MENU.INI","DIALOG.RSP","DOSBOX/DOSBox.exe"})Require(File.Exists(Path.Combine(source,f)),"GOG-Datei fehlt: "+f);long total=files.Sum(f=>new FileInfo(Path.Combine(source,f)).Length);long cdBytes=Rules.SelectNodes("/HarvesterPatch/Image").Cast<XmlNode>().Sum(e=>new FileInfo(Path.Combine(source,A(e,"name"))).Length);var drive=new DriveInfo(Path.GetPathRoot(target));Require(drive.AvailableFreeSpace>checked(total+3*cdBytes+900000000L),"Zu wenig freier Speicher fuer sichere Kopie und 6 Video-CD-Abbilder");string stage=target+".UNFERTIG_"+Guid.NewGuid().ToString("N").Substring(0,8);Directory.CreateDirectory(stage);Console.WriteLine("Erstelle neue Kopie: "+target);var original=new Dictionary<string,string>();foreach(string d in dirs)Directory.CreateDirectory(Path.Combine(stage,d));int count=0;foreach(string f in files){string src=Path.Combine(source,f),dst=Path.Combine(stage,f);string hash=Hash(src);File.Copy(src,dst,false);Require(Hash(dst)==hash,"Kopierfehler: "+f);original.Add(f,hash);if(++count%20==0)Console.WriteLine("Kopie: "+count+" / "+files.Count);}foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Image")){string name=A(e,"name");Console.WriteLine("Uebersetze und pruefe "+name);string work=Path.Combine(stage,"_PATCH_TEMP");Directory.CreateDirectory(work);PatchImage(Path.Combine(stage,name),e,work);Directory.Delete(work,true);}BuildVideoModes(stage,videoManifest);foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Loose")){string dst=Path.Combine(stage,A(e,"path"));Directory.CreateDirectory(Path.GetDirectoryName(dst));if(File.Exists(dst)){File.SetAttributes(dst,FileAttributes.Normal);File.Delete(dst);}File.Copy(Assets[A(e,"asset")],dst,false);}PatchExe(Path.Combine(stage,"HARVEST.EXE"));GogLog(Path.Combine(stage,"goglog.ini"),target);CreateModeLaunchers(stage);var changed=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"HARVEST.DAT","HARVEST3.DAT","HARVEST4.DAT","HARVEST.EXE","goglog.ini"};foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Loose"))changed.Add(A(e,"path").Replace('/',Path.DirectorySeparatorChar));foreach(var f in original){Require(Hash(Path.Combine(source,f.Key))==f.Value,"Quelle wurde zwischenzeitlich geaendert: "+f.Key);if(!changed.Contains(f.Key))Require(Hash(Path.Combine(stage,f.Key))==f.Value,"Unbeteiligte Kopiedatei veraendert: "+f.Key);}var proof=new XmlDocument();var top=proof.CreateElement("HarvesterDeutschInstallation");proof.AppendChild(top);top.SetAttribute("original",source);top.SetAttribute("ziel",target);top.SetAttribute("regeln_sha256",RulesHash);foreach(string f in Directory.GetFiles(stage,"*",SearchOption.AllDirectories)){var e=proof.CreateElement("Datei");e.SetAttribute("pfad",f.Substring(stage.Length+1));e.SetAttribute("sha256",Hash(f));top.AppendChild(e);}proof.Save(Path.Combine(stage,"Deutsch_Pruefnachweis.xml"));Require(!Directory.Exists(target)&&!File.Exists(target),"Ziel entstand zwischenzeitlich");Directory.Move(stage,target);Console.WriteLine("\nERFOLG: "+target+"\nStart: 3 deutsche CMD-Varianten (ohne / 10px / 11px).\nOriginal und vorhandene Spielstaende bleiben unveraendert.");}
 static string DetectOriginal(){foreach(var view in new[]{Microsoft.Win32.RegistryView.Registry32,Microsoft.Win32.RegistryView.Registry64})foreach(var hive in new[]{Microsoft.Win32.RegistryHive.LocalMachine,Microsoft.Win32.RegistryHive.CurrentUser}){try{using(var root=Microsoft.Win32.RegistryKey.OpenBaseKey(hive,view))using(var key=root.OpenSubKey("Software\\GOG.com\\Games\\1207661373",false)){if(key==null)continue;string dos=key.GetValue("DOSBOXFOLDER") as string;string game=string.IsNullOrEmpty(dos)?null:Path.GetDirectoryName(Full(dos));if(game!=null && new[]{"HARVEST.EXE","HARVEST.DAT","HARVEST3.DAT","HARVEST4.DAT"}.All(f=>File.Exists(Path.Combine(game,f))))return game;}}catch{}}return null;}
 [STAThread] static int Main(string[] args){bool interactive=args.Length==0;try{string rulefile=Path.Combine(Package,"Regeln.xml");Require(Hash(rulefile)==RulesHash,"Regeln.xml fehlt oder ist beschaedigt");Rules.Load(rulefile);foreach(XmlNode e in Rules.SelectNodes("/HarvesterPatch/Assets/Asset")){string name=A(e,"name");Require(Path.GetFileName(name)==name,"Unsicherer Paketpfad");string p=Path.Combine(Package,"Daten",name);Require(new FileInfo(p).Length==long.Parse(A(e,"size"))&&Hash(p)==A(e,"sha"),"Uebersetzungsdatei fehlt/beschaedigt");Assets.Add(name,p);}string source=null,target=null;if(interactive){Application.EnableVisualStyles();using(var dialog=new FolderBrowserDialog()){dialog.Description="Englischen GOG-Originalordner mit HARVEST.EXE und den drei DAT-CD-Abbildern auswaehlen";dialog.ShowNewFolderButton=false;string detected=DetectOriginal();if(detected!=null)dialog.SelectedPath=detected;if(dialog.ShowDialog()!=DialogResult.OK)return 0;source=dialog.SelectedPath;}using(var destination=new FolderBrowserDialog()){destination.Description="Speicherort fuer die separate deutsche Kopie auswaehlen. Dort wird Harvester_DE_GOG neu angelegt.";destination.SelectedPath=Path.GetDirectoryName(Full(source));destination.ShowNewFolderButton=true;if(destination.ShowDialog()!=DialogResult.OK)return 0;target=Path.Combine(destination.SelectedPath,"Harvester_DE_GOG");}}else{for(int i=0;i<args.Length;i++){if(args[i]=="--source"&&i+1<args.Length)source=args[++i];else if(args[i]=="--target"&&i+1<args.Length)target=args[++i];else throw new Exception("Unbekannter Parameter");}}Require(!string.IsNullOrEmpty(source),"Originalordner nicht angegeben");if(target==null)target=Path.Combine(Path.GetDirectoryName(Full(source)),"Harvester_DE_GOG");Install(source,target);if(interactive){Console.WriteLine("Taste druecken zum Schliessen.");Console.ReadKey();}return 0;}catch(Exception e){Console.Error.WriteLine("\nSTOP: "+e.Message+"\nDas Original wurde nicht beschrieben. Ein separater UNFERTIG-Ordner kann zur Diagnose zurueckbleiben.");if(interactive){Console.WriteLine("Taste druecken zum Schliessen.");Console.ReadKey();}return 1;}}
